const STATUS = { finding: { es: 'Identificando el proceso', en: 'Identifying the process' } };
const lang = $json.language || 'es';
return [{ json: { ...$json, status_text: STATUS.finding[lang] } }];

const data = $('Status Text: Finding').first().json;
const { language, current_date, github_owner, github_repo, github_tag, message, focus } = data;
const ref = github_tag || 'main';
const focusBlock = focus
  ? `USER'S CURRENT FOCUS (from Agent: Intention Focus -- grounding context, not a directive; use it to inform your own judgment, don't just defer to it):\n${focus}\n\n`
  : '';
const chatInput = `Today: ${current_date}. Respond in: ${language}.
${focusBlock}
STEPS:
1. Call get_file_contents with owner=${github_owner}, repo=${github_repo}, path={organization.target}/index.json, ref=${ref}. Resolve {organization.target} from the INPUT JSON below. Always call this first.
2. Match the user message to one index entry using: keywords → when_to_use → name/slug.

INPUT:
\`\`\`json
${JSON.stringify(data, null, 2)}
\`\`\``;
return [{ json: { ...data, chatInput } }];

const base = $json;
const content = base._parsed || {};

// Deliberately never produces 'sap_inquiry_execution' -- matches v13, where Agent: Find
// never decided execute-vs-fill-form either (that came from a separate form_state.ready
// check run AFTER Agent: Form updated it, not from classifying the incoming message).
// SAP: Process Form Filling calls SAP: Inquiry Execution internally once it marks
// form_state.ready = true, in the same turn -- so it can reopen the form itself (with the
// specific field SAP rejected) if execution comes back needing a correction, without
// bouncing back out through this Router. A message that abandons the correction entirely
// ('never mind, do X instead') is still caught independently: it's just a fresh new_intent
// on the next turn, same as any other intent switch.
let route_key = null;
let needsErrorParse = false;
let errorCode = null;
let errorMessage = null;
let activeNodeId = base.active_node_id;
let intentionNodes = base.intention_nodes || {};
let resetProcess = false;

if (content.status === 'general_inquiry') {
  route_key = 'general_inquiry';
} else if (content.status === 'pending_reply') {
  // pending_reply only ever means the message continues a process that's active and
  // mid-form (form_state.ready not yet true) -- the only case Agent: Find can even reach
  // this status for, since it's the only pending_reply case in its systemMessage. But
  // Agent: Find is an LLM classification over conversation memory, not a guaranteed-
  // correct read of live state -- verify the node it's continuing is genuinely still
  // 'active' before committing to this route, instead of trusting active_node_id blindly.
  // A node that's already 'completed'/'abandoned' has had its process_definition pruned
  // to just {name} (Register Node/Compute Execution Outcome do this the moment a node
  // reaches 'completed' -- it's never meant to execute again); dispatching into
  // form-filling/execution against it used to crash deep inside SAP execution instead of
  // failing cleanly right here, at the actual decision to route -- this is that fix.
  const activeNode = intentionNodes[base.active_node_id];
  if (activeNode?.status === 'active') {
    route_key = 'sap_form_filling';
  } else {
    // The node this message thought it was continuing can't be re-entered -- hand
    // control back to whatever it might itself have interrupted, same as any other
    // terminal transition. Same TERMINAL_STATUSES/walk shape duplicated in Park Current
    // Intent (intent-manager.json), Compute Execution Outcome
    // (sap-inquiry-execution.json), Compute Form Outcome
    // (sap-process-form-filling.json), Classify & Store Error (error-parser.json), and
    // Resolve Final State (batch-processing.json) -- keep all six in sync if this changes.
    const TERMINAL_STATUSES = new Set(['completed', 'abandoned']);
    const findResumeTarget = (nodeId, nodes) => {
      let current = nodeId;
      while (current) {
        const node = nodes[current];
        if (!node) return null;
        if (!TERMINAL_STATUSES.has(node.status)) return current;
        current = node.parent_id;
      }
      return null;
    };
    const resumeTargetId = findResumeTarget(activeNode?.parent_id, intentionNodes);
    if (resumeTargetId) {
      intentionNodes = { ...intentionNodes, [resumeTargetId]: { ...intentionNodes[resumeTargetId], status: 'active' } };
    }
    activeNodeId = resumeTargetId;
    resetProcess = true;
    needsErrorParse = true;
    errorCode = 'NOT_FOUND';
  }
} else if (content.status === 'new_intent') {
  const status = content.new_intent_status;
  // Parking an already-active process before a new one starts is Intent Manager's job now
  // -- unconditional, before this ever reaches the Router -- not this node's concern.
  // Form Filling and Batch Processing still only ever receive a new_intent/match|batch on
  // a clean slate (no process_id), because Intent Manager clears it first when needed.
  if (status === 'match') {
    route_key = 'sap_form_filling';
  } else if (status === 'batch') {
    route_key = 'batch_processing';
  } else if (status === 'discover') {
    route_key = 'sap_discovery';
  } else if (status === 'no_match') {
    needsErrorParse = true;
    errorCode = 'NO_MATCH';
    errorMessage = content.message || null;
  } else if (status === 'error') {
    needsErrorParse = true;
    errorCode = 'AGENT_ERROR';
    errorMessage = content.message || null;
  }
}

// A response this node can't recognize at all (unparseable, or a status/new_intent_status
// combination outside the table above) is itself worth surfacing rather than silently
// routing nowhere -- classified and delivered right here, same as any other classification
// failure. Intent Manager is never involved in this -- it already happens in each route.
if (!route_key || base._parse_error) {
  needsErrorParse = true;
  errorCode = errorCode || 'PARSE_ERROR';
  errorMessage = errorMessage || content.message || null;
}

// content.form_state and content.message are both vestiges of Agent: Find's own output
// contract for new_intent classifications (form_state always null; message null on
// match/batch, or the agent's own generated text on no_match/error) -- both excluded from
// the spread deliberately. form_state: if a process is already active when a genuinely new
// intent arrives, that process's real, already-collected form_state is still sitting on
// base at this point, and Intent Manager (running right after this file) needs it intact
// to snapshot into the paused node. message: base.message is the user's real chat input,
// needed unchanged all the way down through Context Update and into whichever flow the
// Router dispatches to (e.g. Agent: Form reads it directly) -- letting either of these
// null/agent-authored values spread over the real upstream field would silently destroy
// it for every node downstream of this one.
const { form_state: _unusedFormState, message: _unusedMessage, ...restContent } = content;

return [{ json: {
  ...base,
  ...restContent,
  route_key,
  active_node_id: activeNodeId,
  intention_nodes: intentionNodes,
  reset_process: resetProcess,
  _needs_error_parse: needsErrorParse,
  ...(needsErrorParse ? { error: errorCode, error_message: errorMessage } : {}),
} }];

// Runs before Agent: Find so classification never has to reconstruct "why" from raw
// state alone. Builds the full intention tree (every node, any status -- a paused root, a
// completed side-query, the current active leaf -- all correctly nested via parent_id) so
// Agent: Intention Focus can see the whole shape of what's been going on, not just the
// current node in isolation. Reads straight off the trigger's own payload since nothing
// upstream has run yet to wipe it.
const data = $input.first().json;
const { message, intention_nodes } = data;
const nodes = Object.values(intention_nodes || {});

function missingRequiredFields(node) {
  const sections = node.process_definition?.form?.sections || [];
  const formState = node.form_state || {};
  const missing = [];
  for (const section of sections) {
    for (const field of section.fields || []) {
      if (field.required && formState[field.id] == null) missing.push(field.label || field.id);
    }
  }
  return missing;
}

function buildTree(parentId) {
  return nodes
    .filter((n) => (n.parent_id || null) === parentId)
    .map((n) => ({
      process: n.process_definition?.name || n.process_id,
      status: n.status,
      ...(n.status === 'active' || n.status === 'paused' ? { missing_required_fields: missingRequiredFields(n) } : {}),
      children: buildTree(n.id),
    }));
}

const intentionTree = buildTree(null);

const chatInput = `USER MESSAGE:
${message}

INTENTION TREE (structural grounding only, not to repeat verbatim -- every intention so far, nested by which one each interrupted; empty if this is a fresh session):
\`\`\`json
${JSON.stringify(intentionTree, null, 2)}
\`\`\``;

return [{ json: { ...data, chatInput } }];

const base = $('Prompt: Intention Focus').first().json;
const current = $json;
// A focus-agent failure is not fatal to the turn -- Agent: Find still works fine on its
// own raw state without this extra grounding, so this degrades gracefully (focus: null)
// instead of surfacing as a real error the way Agent: Find's own failures must.
if (current.error) {
  return [{ json: { ...base, focus: null } }];
}
let focus = null;
try {
  focus = JSON.parse((current.output || '').trim()).focus ?? null;
} catch {
  focus = null;
}
return [{ json: { ...base, focus } }];
